function splitAB(text) {
  const m = text.match(/^(.*?)(?:A[.．]\s*)(.*?)[；;](?:B[.．]\s*)(.*?)[。.]?$/);
  if (!m) return { lead: "请在两个方案中选择一个。", options: [text, "按另一方案处理"] };
  return { lead: m[1].trim() || "请在两个方案中选择一个。", options: [m[2].trim(), m[3].trim()] };
}

const all = [
  ...bribeRows.map(([id,title,visitor,text],i) => ({ id, title, visitor, text, type: "bribe", carrier: carrierProfiles[i%carrierProfiles.length], appearance: visitorAppearances[i%visitorAppearances.length], opening: openingLines[i%openingLines.length], request: requestLines[(i*5)%requestLines.length], offer: offerLines[(i*3)%offerLines.length] })),
  ...decisionRows.map(([id,title,text]) => ({ id, title, text, type: id.includes("-P") ? "performance" : "ordinary", ...splitAB(text) }))
];

window.MATERIALS = ["A","B","C"].reduce((out, set) => {
  out[set] = all.filter(x => x.id.startsWith(`${set}-`));
  return out;
}, {});
